parameters.jsCode:
// Antwortentwurf aus Vorlagen. Bewusst ohne LLM: Alle Inhalte liegen nach der AB-Prüfung strukturiert vor.
// Ein 7B-Modell hielt sich beim Formulieren nicht zuverlässig an die Regeln (zweite Anrede, Floskeln, Zusagen).
// Vorlagen sind verlässlich, sofort fertig und können nichts erfinden. Senden tut immer der Mitarbeiter.
const f = $('Formular Antwortentwurf').item.json;
const t = $json;
const ab = t.ab_pruefung ?? {};
const foermlich = f['Förmlichkeit'] === 'förmlich';
const nachdruck = f.Nachdruck === 'mit Nachdruck';
const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
const datum = (d) => (d ? (typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.') : '[Termin]');
const termin = t.liefertermin ?? '[Termin]';

// Je Anliegen zwei Fassungen: [gelassen, mit Nachdruck]
const saetze = [];
for (const a of ab.abweichungen ?? []) {
  const s = {
    preis: [
      `Sie haben einen Einzelpreis von ${zahl(a.bestaetigt)} ${a.waehrung} bestätigt, bestellt war ${zahl(a.bestellt)} ${a.waehrung}. Können Sie uns die Änderung bitte erläutern?`,
      `Den bestätigten Einzelpreis von ${zahl(a.bestaetigt)} ${a.waehrung} können wir so nicht akzeptieren, bestellt war ${zahl(a.bestellt)} ${a.waehrung}. Bitte liefern Sie zum bestellten Preis oder begründen Sie die Erhöhung.`],
    menge: [
      `Sie haben ${zahl(a.bestaetigt)} Stück bestätigt, bestellt waren ${zahl(a.bestellt)} Stück${a.grund ? ` (Ihre Begründung: ${a.grund})` : ''}. Zur geänderten Menge: [annehmen oder ablehnen].`,
      `Sie haben ${zahl(a.bestaetigt)} Stück bestätigt, bestellt waren ${zahl(a.bestellt)} Stück${a.grund ? ` (Ihre Begründung: ${a.grund})` : ''}. Zur geänderten Menge: [annehmen oder ablehnen].`],
    stammdaten_pruefen: [
      'Bitte bestätigen Sie uns die richtige Verpackungseinheit kurz schriftlich, dann passen wir unsere Stammdaten an.',
      'Bitte bestätigen Sie uns die richtige Verpackungseinheit schriftlich, damit wir unsere Stammdaten korrigieren und künftige Bestellungen stimmen.'],
    termin_unsicher: [
      `Den Liefertermin haben Sie noch nicht verbindlich zugesagt, gewünscht war der ${datum(a.gewuenscht)}. Bitte nennen Sie uns einen verbindlichen Termin, sobald er feststeht.`,
      `Wir benötigen einen verbindlichen Liefertermin, gewünscht war der ${datum(a.gewuenscht)}. Ein Termin ohne Gewähr reicht uns für die Planung nicht aus.`],
    termin_fehlt: [
      `In Ihrer Bestätigung fehlt der Liefertermin, gewünscht war der ${datum(a.gewuenscht)}. Bitte ergänzen Sie ihn noch.`,
      `In Ihrer Bestätigung fehlt der Liefertermin. Bitte bestätigen Sie uns den Wunschtermin ${datum(a.gewuenscht)} oder nennen Sie einen verbindlichen Termin.`],
    termin_spaeter: [
      `Bestätigt haben Sie den ${datum(a.bestaetigt)}, gewünscht war der ${datum(a.gewuenscht)}. Ist der Wunschtermin oder eine Teillieferung bis dahin möglich?`,
      `Der bestätigte Termin ${datum(a.bestaetigt)} liegt nach unserem Wunschtermin ${datum(a.gewuenscht)}. Bitte prüfen Sie, ob Sie den Wunschtermin oder zumindest eine Teillieferung bis dahin halten können.`],
  }[a.art];
  if (s) saetze.push(s[nachdruck ? 1 : 0]);
}
for (const g of ab.pruefgruende ?? []) {
  const s = {
    neuer_lieferant: [
      `Wir freuen uns auf die Zusammenarbeit. Bitte nennen Sie uns einen festen Ansprechpartner für die Auftragsabwicklung und bestätigen Sie den Liefertermin ${termin} verbindlich.`,
      `Da dies unsere erste Serienbestellung bei Ihnen ist, bitten wir um einen festen Ansprechpartner für die Auftragsabwicklung und eine verbindliche Zusage des Liefertermins ${termin}.`],
    liefertreue_unter_schwelle: [
      `Bitte sagen Sie uns den Liefertermin ${termin} verbindlich zu und geben Sie frühzeitig Bescheid, falls er sich verschiebt.`,
      `Bitte sagen Sie uns den Liefertermin ${termin} ausdrücklich verbindlich zu. Bei einer Verschiebung erwarten wir eine sofortige Information, nicht erst am Liefertag.`],
    blindbestaetigung_verdacht: [
      'Ihre Bestätigung kam sehr schnell. Können Sie uns kurz bestätigen, dass Termin und Menge mit der Fertigung abgestimmt sind?',
      'Ihre Bestätigung kam wenige Minuten nach der Bestellung. Bitte bestätigen Sie uns, dass Termin und Menge tatsächlich mit der Fertigung abgestimmt sind.'],
    absender_domain_abweichend: [
      'Ihre Bestätigung kam von einer uns unbekannten Absenderadresse. Bitte senden Sie die Auftragsbestätigung noch einmal über Ihre bekannte Adresse.',
      'Ihre Bestätigung kam von einer uns unbekannten Absenderadresse. Bitte senden Sie die Auftragsbestätigung erneut über Ihre bekannte Adresse, vorher können wir sie nicht berücksichtigen.'],
  }[g];
  if (s) saetze.push(s[nachdruck ? 1 : 0]);
}
if (f.Anliegen) saetze.push(f.Anliegen.trim());
if (!saetze.length) saetze.push('[Anliegen]');

const nachname = (t.ansprechpartner ?? '').split(' ').slice(-1)[0];
const anrede = !nachname
  ? (foermlich ? 'Sehr geehrte Damen und Herren,' : 'Hallo,')
  : foermlich
    ? `${t.anrede === 'Frau' ? 'Sehr geehrte Frau' : 'Sehr geehrter Herr'} ${nachname},`
    : `Hallo ${t.anrede} ${nachname},`;
const einleitung = foermlich
  ? `vielen Dank für Ihre Auftragsbestätigung zu unserer Bestellung ${t.bestellnummer} (${t.artikel}).`
  : `danke für Ihre AB zu unserer Bestellung ${t.bestellnummer} (${t.artikel}).`;
const frist = nachdruck ? [foermlich ? 'Bitte geben Sie uns bis [Datum] Rückmeldung.' : 'Eine Rückmeldung bis [Datum] wäre wichtig.'] : [];
const gruss = foermlich ? 'Mit freundlichen Grüßen' : 'Viele Grüße';

const text = [anrede, '', einleitung, '', ...saetze.flatMap((s) => [s, '']), ...frist, ...(frist.length ? [''] : []),
  gruss, t.einkaeufer ?? '[Name]', 'Hagemann Antriebstechnik GmbH'].join('\n');
const platzhalter = [...new Set(text.match(/\[[^\]]+\]/g) ?? [])];

return {
  json: {
    ticket_id: t.id,
    empfaenger: t.absender,
    betreff: `Ihre Auftragsbestätigung zu Bestellung ${t.bestellnummer}${(ab.abweichungen ?? []).length ? ': Rückfrage' : ''}`,
    text,
    foermlichkeit: f['Förmlichkeit'],
    nachdruck: f.Nachdruck,
    erstellt_von: f['Erstellt von'],
    warnungen: platzhalter.map((p) => `Platzhalter ausfüllen: ${p}`),
  },
};

parameters.query:
INSERT INTO entwuerfe (ticket_id, empfaenger, betreff, text, foermlichkeit, nachdruck, erstellt_von, warnungen)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8::jsonb)
RETURNING id, betreff, text, warnungen;

parameters.completionMessage:
={{ `${$json.betreff}

${$json.text}` + ($json.warnungen.length ? `

Bitte prüfen: ${$json.warnungen.join(', ')}` : '') + '

Der Entwurf steht auch auf der Arbeitsliste.' }}
